INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('SOCI.G9.SOCIAL.PATHWAY_CHOICES.PATHWAYS', 'SOCI.G9.SOCIAL.PATHWAY_CHOICES', 'social_studies', 9, 'Name the senior school pathways and what to weigh in choosing one', ARRAY['SOCI.G9.SOCIAL.PATHWAY_CHOICES.a', 'SOCI.G9.SOCIAL.PATHWAY_CHOICES.b']::text[], 'The child names the three pathways (STEM; Social Sciences; Arts and Sports Science) and the factors for choosing (interests, abilities, career goals, performance and the subjects offered), and says a pathway is chosen with parents, teachers and counsellors. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["pick the right answer","pick the right answer in a short story","find the false step in a learner''s reason"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('SOCI.G9.SOCIAL.PRE_CAREER_SUPPORT_SYSTE.PRE_CAREER', 'SOCI.G9.SOCIAL.PRE_CAREER_SUPPORT_SYSTE', 'social_studies', 9, 'Name pre-career support systems and why mapping matters', ARRAY['SOCI.G9.SOCIAL.PRE_CAREER_SUPPORT_SYSTE.a', 'SOCI.G9.SOCIAL.PRE_CAREER_SUPPORT_SYSTE.d']::text[], 'The child names support systems (parents, teachers, counsellors, mentors, career talks, school clubs), and says pre-career mapping helps a learner link interests and abilities to careers. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["pick the right answer","pick the right answer in a short story","find the false step in a learner''s reason"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('SOCI.G9.SOCIAL.PRE_CAREER_SUPPORT_SYSTE.SUPPORT_CHALLENGES', 'SOCI.G9.SOCIAL.PRE_CAREER_SUPPORT_SYSTE', 'social_studies', 9, 'Analyse challenges in pre-career support systems and choose solutions', ARRAY['SOCI.G9.SOCIAL.PRE_CAREER_SUPPORT_SYSTE.b', 'SOCI.G9.SOCIAL.PRE_CAREER_SUPPORT_SYSTE.c']::text[], 'The child names challenges in support systems (too few counsellors, little career information in rural schools, pressure from parents to follow a set career, costly mentorship, misinformation online) and pairs each with a sensible solution (peer mentors, career days and visits, talking openly with parents, free online and school career guidance, checking sources). Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["pick the right answer","pick the right answer in a short story","find the false step in a learner''s reason"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('SOCI.G9.COMMUN.COMMUNITY_SERVICE_LEARNI.CSL_STEPS', 'SOCI.G9.COMMUN.COMMUNITY_SERVICE_LEARNI', 'social_studies', 9, 'Put the steps of a community service project in order', ARRAY['SOCI.G9.COMMUN.COMMUNITY_SERVICE_LEARNI.a', 'SOCI.G9.COMMUN.COMMUNITY_SERVICE_LEARNI.b', 'SOCI.G9.COMMUN.COMMUNITY_SERVICE_LEARNI.c']::text[], 'The child gives the order identify the problem, design a solution, plan, implement, then report, and says a problem is found by observing and asking the community. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["pick the right answer","pick the right answer in a short story","find the false step in a learner''s reason"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('SOCI.G9.PEOPLE.SOCIO_ECONOMIC_PRACTICES.STONE_AGE', 'SOCI.G9.PEOPLE.SOCIO_ECONOMIC_PRACTICES', 'social_studies', 9, 'Describe the Stone Age practices and tools of early humans in Africa', ARRAY['SOCI.G9.PEOPLE.SOCIO_ECONOMIC_PRACTICES.a', 'SOCI.G9.PEOPLE.SOCIO_ECONOMIC_PRACTICES.b']::text[], 'The child says early humans were hunters and gatherers who lived in caves or rock shelters, made tools of stone (hand axes, choppers, flakes), later used fire and made small tools, and that Olduvai Gorge and Olorgesailie are famous sites. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["pick the right answer","pick the right answer in a short story","find the false step in a learner''s reason"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('SOCI.G9.PEOPLE.INDIGENOUS_KNOWLEDGE_SYS.INDIGENOUS_KNOWLEDGE', 'SOCI.G9.PEOPLE.INDIGENOUS_KNOWLEDGE_SYS', 'social_studies', 9, 'Name indigenous knowledge systems and what they were used for', ARRAY['SOCI.G9.PEOPLE.INDIGENOUS_KNOWLEDGE_SYS.a', 'SOCI.G9.PEOPLE.INDIGENOUS_KNOWLEDGE_SYS.b']::text[], 'The child names oral literature (proverbs, stories, riddles), herbal medicine, weather forecasting, farming and craft skills, and says elders passed them on by word of mouth so that life could continue. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["pick the right answer","pick the right answer in a short story","find the false step in a learner''s reason"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('SOCI.G9.PEOPLE.POVERTY_REDUCTION.POVERTY', 'SOCI.G9.PEOPLE.POVERTY_REDUCTION', 'social_studies', 9, 'Name causes of poverty in Africa and the effect of overexploitation', ARRAY['SOCI.G9.PEOPLE.POVERTY_REDUCTION.a', 'SOCI.G9.PEOPLE.POVERTY_REDUCTION.b']::text[], 'The child names causes (unemployment, drought, poor governance and corruption, conflict, low education, rapid population growth) and says overexploiting resources (cutting trees, overfishing, over-mining) can empty resources and deepen poverty. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["pick the right answer","pick the right answer in a short story","find the false step in a learner''s reason"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('SOCI.G9.PEOPLE.POPULATION_STRUCTURE.POPULATION', 'SOCI.G9.PEOPLE.POPULATION_STRUCTURE', 'social_studies', 9, 'Name sources of population data and read population structure', ARRAY['SOCI.G9.PEOPLE.POPULATION_STRUCTURE.a', 'SOCI.G9.PEOPLE.POPULATION_STRUCTURE.b']::text[], 'The child names the census, sample surveys and registration of births and deaths as sources, and says a developing country such as Kenya has a wide-based pyramid (many children) and a developed country such as Germany has a narrower base (older population). Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["pick the right answer","pick the right answer in a short story","find the false step in a learner''s reason"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('SOCI.G9.PEOPLE.POPULATION_STRUCTURE.POP_PYRAMIDS', 'SOCI.G9.PEOPLE.POPULATION_STRUCTURE', 'social_studies', 9, 'Read age-sex pyramids and say how population structure guides the sharing of national resources', ARRAY['SOCI.G9.PEOPLE.POPULATION_STRUCTURE.c', 'SOCI.G9.PEOPLE.POPULATION_STRUCTURE.d']::text[], 'The child reads an age-sex pyramid (males on one side, females on the other, the youngest at the base), tells a developing country''s wide base from a developed country''s narrow base and wide top, works out the dependants, and says a young population needs more schools, health care for mothers and children and jobs, while an older one needs pensions and care for the aged. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["pick the right answer","pick the right answer in a short story","find the false step in a learner''s reason"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('SOCI.G9.PEOPLE.PEACEFUL_CONFLICT_RESOLU.PEACE', 'SOCI.G9.PEOPLE.PEACEFUL_CONFLICT_RESOLU', 'social_studies', 9, 'Name types of peace and barriers to resolving conflict', ARRAY['SOCI.G9.PEOPLE.PEACEFUL_CONFLICT_RESOLU.a', 'SOCI.G9.PEOPLE.PEACEFUL_CONFLICT_RESOLU.b']::text[], 'The child names inner peace, peace between people, community peace and national peace, and barriers (anger, prejudice, mistrust, poor communication), and says emotional intelligence helps handle anger. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["pick the right answer","pick the right answer in a short story","find the false step in a learner''s reason"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('SOCI.G9.PEOPLE.PEACEFUL_CONFLICT_RESOLU.EMOTIONS_PEACE', 'SOCI.G9.PEOPLE.PEACEFUL_CONFLICT_RESOLU', 'social_studies', 9, 'Choose ways of managing emotions and using emotional intelligence to resolve conflict', ARRAY['SOCI.G9.PEOPLE.PEACEFUL_CONFLICT_RESOLU.c', 'SOCI.G9.PEOPLE.PEACEFUL_CONFLICT_RESOLU.d']::text[], 'The child names the parts of emotional intelligence (knowing your own feelings, managing them, motivating yourself, empathy, social skills), picks ways to manage strong emotions (pause, breathe, count, walk away, talk to a trusted person) and applies them to a community conflict by listening, seeing the other side and speaking calmly. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["pick the right answer","pick the right answer in a short story","find the false step in a learner''s reason"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('SOCI.G9.PEOPLE.HEALTHY_RELATIONSHIPS.RELATIONSHIPS', 'SOCI.G9.PEOPLE.HEALTHY_RELATIONSHIPS', 'social_studies', 9, 'Name ways of sustaining healthy relationships and barriers to them', ARRAY['SOCI.G9.PEOPLE.HEALTHY_RELATIONSHIPS.a', 'SOCI.G9.PEOPLE.HEALTHY_RELATIONSHIPS.b']::text[], 'The child names respect, honest talk, trust, forgiveness and listening as ways to sustain a relationship, and jealousy, mistrust, gossip and peer pressure as barriers. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["pick the right answer","pick the right answer in a short story","find the false step in a learner''s reason"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('SOCI.G9.NATURA.TOPOGRAPHICAL_MAPS.TOPO_MAPS', 'SOCI.G9.NATURA.TOPOGRAPHICAL_MAPS', 'social_studies', 9, 'Read human activities and scale work on topographical maps', ARRAY['SOCI.G9.NATURA.TOPOGRAPHICAL_MAPS.a', 'SOCI.G9.NATURA.TOPOGRAPHICAL_MAPS.b', 'SOCI.G9.NATURA.TOPOGRAPHICAL_MAPS.c']::text[], 'The child says a topographical map shows settlements, roads, railways, farms and markets by symbols, contour lines show height, a cross-section shows the shape of the land along a line, and a map is enlarged or reduced by changing the scale. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["pick the right answer","pick the right answer in a short story","find the false step in a learner''s reason"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('SOCI.G9.NATURA.INTERNAL_LAND_FORMING_PR.LAND_FORMING', 'SOCI.G9.NATURA.INTERNAL_LAND_FORMING_PR', 'social_studies', 9, 'Name earth movements, faulting features and their effects', ARRAY['SOCI.G9.NATURA.INTERNAL_LAND_FORMING_PR.a', 'SOCI.G9.NATURA.INTERNAL_LAND_FORMING_PR.c', 'SOCI.G9.NATURA.INTERNAL_LAND_FORMING_PR.d']::text[], 'The child says tensional forces pull the crust apart and compressional forces push it together, that faulting makes rift valleys, block mountains and escarpments, that the Great Rift Valley crosses Kenya, and that faulting brings earthquakes, lakes and hot springs. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["pick the right answer","pick the right answer in a short story","find the false step in a learner''s reason"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('SOCI.G9.NATURA.INTERNAL_LAND_FORMING_PR.PLATE_TECTONICS', 'SOCI.G9.NATURA.INTERNAL_LAND_FORMING_PR', 'social_studies', 9, 'Explain continental drift and plate tectonics in the formation of continents', ARRAY['SOCI.G9.NATURA.INTERNAL_LAND_FORMING_PR.b']::text[], 'The child says continental drift is the idea (Alfred Wegener) that the continents were once one land mass, Pangaea, that slowly split and moved apart, gives evidence (the coasts of Africa and South America fit, matching rocks and fossils), and says plate tectonics explains it: the crust is broken into plates that move on the mantle, and where plates pull apart or push together we get rift valleys, mountains, earthquakes and volcanoes. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["pick the right answer","pick the right answer in a short story","find the false step in a learner''s reason"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('SOCI.G9.NATURA.MULTI_PURPOSE_RIVER_PROJ.RIVER_PROJECTS', 'SOCI.G9.NATURA.MULTI_PURPOSE_RIVER_PROJ', 'social_studies', 9, 'Name multi-purpose river projects in Africa and their uses and challenges', ARRAY['SOCI.G9.NATURA.MULTI_PURPOSE_RIVER_PROJ.a', 'SOCI.G9.NATURA.MULTI_PURPOSE_RIVER_PROJ.c', 'SOCI.G9.NATURA.MULTI_PURPOSE_RIVER_PROJ.d']::text[], 'The child names Aswan High Dam on the Nile, Kariba on the Zambezi, Akosombo on the Volta and the Seven Forks on the Tana, and says they give electricity, irrigation, water, flood control and fish, with challenges of high cost, displaced people and silting. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["pick the right answer","pick the right answer in a short story","find the false step in a learner''s reason"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('SOCI.G9.NATURA.MULTI_PURPOSE_RIVER_PROJ.RIVER_CONDITIONS', 'SOCI.G9.NATURA.MULTI_PURPOSE_RIVER_PROJ', 'social_studies', 9, 'Outline the conditions that led to the Tana River projects and choose solutions to river project challenges', ARRAY['SOCI.G9.NATURA.MULTI_PURPOSE_RIVER_PROJ.b', 'SOCI.G9.NATURA.MULTI_PURPOSE_RIVER_PROJ.e']::text[], 'The child gives the conditions for the Seven Forks dams on the Tana (a permanent river with a large volume of water, steep falls and gorges for dam sites, hard rock for foundations, sparse settlement to limit displacement, a growing demand for electricity and irrigation) and pairs challenges (silting, displacement, high cost, water hyacinth, drought lowering water levels) with solutions (planting trees in the catchment, fair compensation and resettlement, loans and partnerships, clearing weeds, other power sources). Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["pick the right answer","pick the right answer in a short story","find the false step in a learner''s reason"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('SOCI.G9.NATURA.MANAGEMENT_AND_CONSERVAT.ENV_DEGRADATION', 'SOCI.G9.NATURA.MANAGEMENT_AND_CONSERVAT', 'social_studies', 9, 'Name causes, effects and answers to environmental degradation', ARRAY['SOCI.G9.NATURA.MANAGEMENT_AND_CONSERVAT.a', 'SOCI.G9.NATURA.MANAGEMENT_AND_CONSERVAT.b', 'SOCI.G9.NATURA.MANAGEMENT_AND_CONSERVAT.c']::text[], 'The child names causes (deforestation, overgrazing, pollution, poor farming), effects (soil erosion, drought, floods, loss of wildlife) and answers (planting trees, terracing, recycling, laws). Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["pick the right answer","pick the right answer in a short story","find the false step in a learner''s reason"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('SOCI.G9.NATURA.WORLD_HERITAGE_SITES_IN_.HERITAGE_SITES', 'SOCI.G9.NATURA.WORLD_HERITAGE_SITES_IN_', 'social_studies', 9, 'Name World Heritage sites in Africa and why they are kept', ARRAY['SOCI.G9.NATURA.WORLD_HERITAGE_SITES_IN_.a', 'SOCI.G9.NATURA.WORLD_HERITAGE_SITES_IN_.b']::text[], 'The child names Lamu Old Town, Fort Jesus, Mount Kenya and Lake Turkana National Parks in Kenya, the Pyramids of Giza in Egypt, the Serengeti in Tanzania and Great Zimbabwe, and says they are kept for culture, tourism and history. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["pick the right answer","pick the right answer in a short story","find the false step in a learner''s reason"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('SOCI.G9.POLITI.THE_CONSTITUTION_OF_KENY.CONSTITUTION_MAKING', 'SOCI.G9.POLITI.THE_CONSTITUTION_OF_KENY', 'social_studies', 9, 'Put the stages of making Kenya''s Constitution in order and name roles', ARRAY['SOCI.G9.POLITI.THE_CONSTITUTION_OF_KENY.a', 'SOCI.G9.POLITI.THE_CONSTITUTION_OF_KENY.b', 'SOCI.G9.POLITI.THE_CONSTITUTION_OF_KENY.c']::text[], 'The child says the stages were collecting views from citizens, drafting, debate by Parliament, a referendum and promulgation in 2010, that Parliament debates and approves the draft, and that citizens give views and vote in the referendum. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["pick the right answer","pick the right answer in a short story","find the false step in a learner''s reason"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('SOCI.G9.POLITI.CIVIC_ENGAGEMENT_IN_GOVE.CIVIC_ENGAGEMENT', 'SOCI.G9.POLITI.CIVIC_ENGAGEMENT_IN_GOVE', 'social_studies', 9, 'Name civic activities, parties and positions in a general election', ARRAY['SOCI.G9.POLITI.CIVIC_ENGAGEMENT_IN_GOVE.a', 'SOCI.G9.POLITI.CIVIC_ENGAGEMENT_IN_GOVE.b', 'SOCI.G9.POLITI.CIVIC_ENGAGEMENT_IN_GOVE.c']::text[], 'The child names voting, attending public forums, paying taxes and joining a party as civic activities, says parties field candidates and give citizens a voice, and names President, Governor, Senator, Member of the National Assembly, Woman Representative and Member of a County Assembly. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["pick the right answer","pick the right answer in a short story","find the false step in a learner''s reason"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('SOCI.G9.POLITI.KENYA_S_BILL_OF_RIGHTS.BILL_OF_RIGHTS', 'SOCI.G9.POLITI.KENYA_S_BILL_OF_RIGHTS', 'social_studies', 9, 'Name rights in Kenya''s Bill of Rights and groups needing special care', ARRAY['SOCI.G9.POLITI.KENYA_S_BILL_OF_RIGHTS.a', 'SOCI.G9.POLITI.KENYA_S_BILL_OF_RIGHTS.b']::text[], 'The child says the Bill of Rights is in Chapter 4 of the 2010 Constitution, names rights (life, equality, expression, privacy, education), and says special groups such as children, persons with disabilities, youth, older persons and minorities are protected. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["pick the right answer","pick the right answer in a short story","find the false step in a learner''s reason"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('SOCI.G9.POLITI.CULTURAL_GLOBALISATION.GLOBAL_CULTURE', 'SOCI.G9.POLITI.CULTURAL_GLOBALISATION', 'social_studies', 9, 'Name cultural elements with global recognition and how to keep them', ARRAY['SOCI.G9.POLITI.CULTURAL_GLOBALISATION.a', 'SOCI.G9.POLITI.CULTURAL_GLOBALISATION.b', 'SOCI.G9.POLITI.CULTURAL_GLOBALISATION.c']::text[], 'The child names language, music, dance, dress, food and sport as elements of culture, says Kiswahili and Kenyan marathon running are recognised in the world, and says respect and dialogue promote a common humanity. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["pick the right answer","pick the right answer in a short story","find the false step in a learner''s reason"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('SOCI.G9.POLITI.CULTURAL_GLOBALISATION.CULTURE_FACTORS', 'SOCI.G9.POLITI.CULTURAL_GLOBALISATION', 'social_studies', 9, 'Name factors that promote healthy cultural relationships in a connected world', ARRAY['SOCI.G9.POLITI.CULTURAL_GLOBALISATION.d']::text[], 'The child names respect and tolerance for other cultures, learning other languages, cultural exchange (festivals, sport, music, exchange programmes), the media used responsibly, travel and tourism, and laws against discrimination as factors that promote healthy cultural relationships, and rejects stereotypes and mockery. Evidence rule: at least four of the last five fresh questions right across at least two question forms, and no repeated pick of the same misconception.', '["pick the right answer","pick the right answer in a short story","find the false step in a learner''s reason"]'::jsonb, '["recall","reasoning"]'::jsonb, ARRAY[]::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('SOCI.G9.SOCIAL.PATHWAY_CHOICES.PATHWAYS', 'SOCI.G8.SOCIAL.SELF_IMPROVEMENT.PERSONALITY', 'skill', 'essential', 'Knowing one''s own traits (Grade 8) is a factor in choosing a pathway. Proposed, to confirm by a CBC Social Studies teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('SOCI.G9.SOCIAL.PATHWAY_CHOICES.PATHWAYS', 'SOCI.G7.SOCIAL.SELF_EXPLORATION.SE_ABILITIES', 'skill', 'essential', 'Abilities and interests (Grade 7) are the first factors for a pathway. Proposed, to confirm by a CBC Social Studies teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('SOCI.G9.SOCIAL.PRE_CAREER_SUPPORT_SYSTE.PRE_CAREER', 'SOCI.G9.SOCIAL.PATHWAY_CHOICES.PATHWAYS', 'skill', 'essential', 'Proposed: this skill builds on it. To confirm by a Social Studies teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('SOCI.G9.SOCIAL.PRE_CAREER_SUPPORT_SYSTE.PRE_CAREER', 'SOCI.G7.SOCIAL.ENTREPRENEURIAL_OPPORTUN.EO_OPPORTUNITY', 'skill', 'essential', 'Matching opportunities to a personality (Grade 7) is the start of career mapping. Proposed, to confirm by a CBC Social Studies teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('SOCI.G9.SOCIAL.PRE_CAREER_SUPPORT_SYSTE.SUPPORT_CHALLENGES', 'SOCI.G9.SOCIAL.PRE_CAREER_SUPPORT_SYSTE.PRE_CAREER', 'skill', 'essential', 'The child must know the support systems before analysing their challenges. Proposed, to confirm by a CBC Social Studies teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('SOCI.G9.SOCIAL.PRE_CAREER_SUPPORT_SYSTE.SUPPORT_CHALLENGES', 'SOCI.G8.PEOPLE.DIVERSITY_AND_INTERPERSO.PEER_PRESSURE', 'skill', 'helpful', 'Handling pressure from others (Grade 8) helps when family or friends push a career. Proposed, to confirm by a CBC Social Studies teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
