INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('SOCI.G9.POLITI.CULTURAL_GLOBALISATION.CULTURE_FACTORS', 'SOCI.G9.POLITI.CULTURAL_GLOBALISATION.GLOBAL_CULTURE', 'skill', 'essential', 'Proposed: this skill builds on it. To confirm by a Social Studies teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('SOCI.G9.POLITI.CULTURAL_GLOBALISATION.CULTURE_FACTORS', 'SOCI.G7.POLITI.CITIZENSHIP.CZ_CITIZEN', 'skill', 'essential', 'Qualities of a global citizen (Grade 7) include respect for other cultures. Proposed, to confirm by a CBC Social Studies teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G9.SOCIAL.PATHWAY_CHOICES.PATHWAYS.M_SS9_PW_NUMBER', 'SOCI.G9.SOCIAL.PATHWAY_CHOICES.PATHWAYS', 'Says there are two senior school pathways (for example sciences and arts), the old split, instead of three.', '{"question":"How many senior school pathways are there?","wrong_answer":"Two","correct_answer":"Three"}'::jsonb, 'Older siblings and parents talk of "sciences or arts", so the child knows two.', 'Offer "Two" next to the right answer and ask the question again in a new situation.', 'Write the three pathways as three columns and sort subjects into them.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G9.SOCIAL.PATHWAY_CHOICES.PATHWAYS.M_SS9_PW_FACTOR', 'SOCI.G9.SOCIAL.PATHWAY_CHOICES.PATHWAYS', 'Chooses a pathway because friends are taking it, not by interests, abilities and career goals.', '{"question":"Which should guide a learner''s choice of pathway?","wrong_answer":"Where her friends are going","correct_answer":"Her interests, abilities and career goals"}'::jsonb, 'Staying with friends feels safer than choosing alone at this age.', 'Offer "Where her friends are going" next to the right answer and ask the question again in a new situation.', 'Fill the interests and abilities sheet first, then look at which pathway fits it.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G9.SOCIAL.PATHWAY_CHOICES.PATHWAYS.M_SS9_PW_NAME', 'SOCI.G9.SOCIAL.PATHWAY_CHOICES.PATHWAYS', 'Names a subject group such as "Trade and Business" as a pathway.', '{"question":"Which is a senior school pathway?","wrong_answer":"Trade and Business only","correct_answer":"Social Sciences"}'::jsonb, 'Subject groups and clusters are mentioned beside pathways and the names blur.', 'Offer "Trade and Business only" next to the right answer and ask the question again in a new situation.', 'List the three pathway names and show the subjects that sit inside each.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G9.SOCIAL.PATHWAY_CHOICES.PATHWAYS.M_SS9_PW_PRESTIGE', 'SOCI.G9.SOCIAL.PATHWAY_CHOICES.PATHWAYS', 'Thinks STEM is the only "good" pathway and the others are for weak learners.', '{"question":"Is the Social Sciences pathway only for learners who cannot do STEM?","wrong_answer":"Yes, STEM is the only good one","correct_answer":"No, each pathway leads to good careers that suit different strengths"}'::jsonb, 'Adults often praise science careers above others.', 'Offer "Yes, STEM is the only good one" next to the right answer and ask the question again in a new context.', 'List careers from each pathway: lawyer, journalist, engineer, sports coach.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G9.SOCIAL.PRE_CAREER_SUPPORT_SYSTE.PRE_CAREER.M_SS9_PC_SUPPORT', 'SOCI.G9.SOCIAL.PRE_CAREER_SUPPORT_SYSTE.PRE_CAREER', 'Names a rumour or what "people say" as a pre-career support system.', '{"question":"Which is a pre-career support system?","wrong_answer":"A rumour","correct_answer":"A school counsellor"}'::jsonb, 'Much career talk the child hears comes from rumour among friends.', 'Offer "A rumour" next to the right answer and ask the question again in a new situation.', 'List trusted sources (counsellor, teacher, mentor, parent) and untrusted ones and sort them.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G9.SOCIAL.PRE_CAREER_SUPPORT_SYSTE.PRE_CAREER.M_SS9_PC_MAP', 'SOCI.G9.SOCIAL.PRE_CAREER_SUPPORT_SYSTE.PRE_CAREER', 'Thinks pre-career mapping fixes one job for life.', '{"question":"What does pre-career mapping do?","wrong_answer":"Fixes the job for life","correct_answer":"Links interests and abilities to careers"}'::jsonb, 'Adults ask "what will you be?" as if there is one answer.', 'Offer "Fixes the job for life" next to the right answer and ask the question again in a new situation.', 'Show that a map links interests to several careers and can change as the learner grows.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G9.SOCIAL.PRE_CAREER_SUPPORT_SYSTE.PRE_CAREER.M_SS9_PC_ONLY', 'SOCI.G9.SOCIAL.PRE_CAREER_SUPPORT_SYSTE.PRE_CAREER', 'Thinks only parents can give career advice.', '{"question":"Who can advise a learner on careers?","wrong_answer":"Only the parents","correct_answer":"Parents, teachers, counsellors and mentors"}'::jsonb, 'Parents are the first and most present advisers in the child''s life.', 'Offer "Only the parents" next to the right answer and ask the question again in a new situation.', 'Make a support web with parents, teachers, counsellors, mentors and faith leaders.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G9.SOCIAL.PRE_CAREER_SUPPORT_SYSTE.PRE_CAREER.M_SS9_PC_SPIRITUAL_NONE', 'SOCI.G9.SOCIAL.PRE_CAREER_SUPPORT_SYSTE.PRE_CAREER', 'Does not count spiritual support as part of a learner''s support system.', '{"question":"How can a faith leader support a learner choosing a career?","wrong_answer":"They cannot","correct_answer":"By giving guidance, encouragement and values"}'::jsonb, 'Career support is pictured as only school and family.', 'Offer "They cannot" next to the right answer and ask the question again in a new context.', 'Add faith leaders to the support web.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G9.SOCIAL.PRE_CAREER_SUPPORT_SYSTE.SUPPORT_CHALLENGES.M_SS9_SC_NO_CHALLENGE', 'SOCI.G9.SOCIAL.PRE_CAREER_SUPPORT_SYSTE.SUPPORT_CHALLENGES', 'Thinks support systems have no challenges.', '{"question":"Give one challenge a rural learner may face in getting career guidance.","wrong_answer":"There are none","correct_answer":"Too few counsellors or little career information"}'::jsonb, 'The child assumes help is always there.', 'Offer "There are none" next to the right answer and ask the question again in a new context.', 'Compare a town school with a career office and a rural school without one.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G9.SOCIAL.PRE_CAREER_SUPPORT_SYSTE.SUPPORT_CHALLENGES.M_SS9_SC_PARENT_FORCE', 'SOCI.G9.SOCIAL.PRE_CAREER_SUPPORT_SYSTE.SUPPORT_CHALLENGES', 'Thinks a learner must always follow the career a parent chooses, whatever their interests.', '{"question":"A parent wants a learner to be a doctor, but the learner loves art. What is a good step?","wrong_answer":"Do what the parent says without talking","correct_answer":"Talk openly with the parent and a counsellor about interests and options"}'::jsonb, 'Obeying parents is a strong value.', 'Offer "Do what the parent says without talking" next to the right answer and ask the question again in a new context.', 'Role-play a respectful talk with a parent.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G9.SOCIAL.PRE_CAREER_SUPPORT_SYSTE.SUPPORT_CHALLENGES.M_SS9_SC_ONLINE_TRUE', 'SOCI.G9.SOCIAL.PRE_CAREER_SUPPORT_SYSTE.SUPPORT_CHALLENGES', 'Believes every career claim found online.', '{"question":"A post says one course guarantees a big salary. What should you do?","wrong_answer":"Believe it","correct_answer":"Check it with a counsellor or an official source"}'::jsonb, 'Online posts look official.', 'Offer "Believe it" next to the right answer and ask the question again in a new context.', 'Compare a post with the official course guide.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G9.SOCIAL.PRE_CAREER_SUPPORT_SYSTE.SUPPORT_CHALLENGES.M_SS9_SC_SOLUTION_MATCH', 'SOCI.G9.SOCIAL.PRE_CAREER_SUPPORT_SYSTE.SUPPORT_CHALLENGES', 'Pairs a challenge with a solution that does not fit (too few counsellors with buying more books).', '{"question":"Which solution fits \"too few counsellors in a school\"?","wrong_answer":"Buy more textbooks","correct_answer":"Train peer mentors and invite visiting counsellors"}'::jsonb, 'The child picks any school improvement.', 'Offer "Buy more textbooks" next to the right answer and ask the question again in a new context.', 'Ask what the problem is missing: people to talk to.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G9.SOCIAL.PRE_CAREER_SUPPORT_SYSTE.SUPPORT_CHALLENGES.M_SS9_SC_COST_ONLY', 'SOCI.G9.SOCIAL.PRE_CAREER_SUPPORT_SYSTE.SUPPORT_CHALLENGES', 'Thinks the only challenge is money.', '{"question":"Besides money, give one challenge in pre-career support.","wrong_answer":"There is none","correct_answer":"Pressure from family or misinformation"}'::jsonb, 'Money is the challenge talked about most.', 'Offer "There is none" next to the right answer and ask the question again in a new context.', 'List challenges in three columns: money, people, information.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G9.COMMUN.COMMUNITY_SERVICE_LEARNI.CSL_STEPS.M_SS9_CS_ORDER', 'SOCI.G9.COMMUN.COMMUNITY_SERVICE_LEARNI.CSL_STEPS', 'Starts the project by writing the report, before any problem is identified.', '{"question":"What is the first step in a community service project?","wrong_answer":"Write the report","correct_answer":"Identify the problem"}'::jsonb, 'The report is the part handed in and marked, so it feels like the first job.', 'Offer "Write the report" next to the right answer and ask the question again in a new situation.', 'Lay the five step cards in a line and ask what each needs from the one before.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G9.COMMUN.COMMUNITY_SERVICE_LEARNI.CSL_STEPS.M_SS9_CS_PLAN', 'SOCI.G9.COMMUN.COMMUNITY_SERVICE_LEARNI.CSL_STEPS', 'Puts writing the report just before implementing, leaving out planning.', '{"question":"What comes before implementing?","wrong_answer":"Writing the report","correct_answer":"Planning"}'::jsonb, 'The child mixes the plan and the report, both written documents.', 'Offer "Writing the report" next to the right answer and ask the question again in a new situation.', 'Hold up a plan (future: who, what, when) and a report (past: what was done) side by side.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G9.COMMUN.COMMUNITY_SERVICE_LEARNI.CSL_STEPS.M_SS9_CS_REPORT', 'SOCI.G9.COMMUN.COMMUNITY_SERVICE_LEARNI.CSL_STEPS', 'Puts identifying the problem last, reversing the order.', '{"question":"What comes last?","wrong_answer":"Identifying the problem","correct_answer":"Writing the report"}'::jsonb, 'The child reads the list from the wrong end.', 'Offer "Identifying the problem" next to the right answer and ask the question again in a new situation.', 'Ask: can you write about results before the work? Put the report last.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G9.COMMUN.COMMUNITY_SERVICE_LEARNI.CSL_STEPS.M_SS9_CS_REPORT_CONTENT', 'SOCI.G9.COMMUN.COMMUNITY_SERVICE_LEARNI.CSL_STEPS', 'Thinks the report only lists who took part.', '{"question":"What should a CSL report include?","wrong_answer":"Only the names of the learners","correct_answer":"The problem, the solution, what was done, the results and the lessons"}'::jsonb, 'Reports at school often begin with names.', 'Offer "Only the names of the learners" next to the right answer and ask the question again in a new context.', 'Give a report frame with five headings.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G9.PEOPLE.SOCIO_ECONOMIC_PRACTICES.STONE_AGE.M_SS9_SA_FARM', 'SOCI.G9.PEOPLE.SOCIO_ECONOMIC_PRACTICES.STONE_AGE', 'Says early Stone Age humans grew crops, putting farming thousands of years too early.', '{"question":"How did early Stone Age humans get food?","wrong_answer":"By farming crops","correct_answer":"By hunting and gathering"}'::jsonb, 'The child thinks people have always farmed, as their own community does.', 'Offer "By farming crops" next to the right answer and ask the question again in a new situation.', 'Put hunting and gathering, then farming, on a timeline with the Stone Age periods.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G9.PEOPLE.SOCIO_ECONOMIC_PRACTICES.STONE_AGE.M_SS9_SA_TOOL', 'SOCI.G9.PEOPLE.SOCIO_ECONOMIC_PRACTICES.STONE_AGE', 'Says Stone Age tools were made of iron.', '{"question":"What were Stone Age tools made of?","wrong_answer":"Iron","correct_answer":"Stone"}'::jsonb, 'Iron tools such as the jembe are the old tools the child knows.', 'Offer "Iron" next to the right answer and ask the question again in a new situation.', 'Compare a stone hand axe with an iron hoe and place each on a timeline.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G9.PEOPLE.SOCIO_ECONOMIC_PRACTICES.STONE_AGE.M_SS9_SA_SITE', 'SOCI.G9.PEOPLE.SOCIO_ECONOMIC_PRACTICES.STONE_AGE', 'Names Fort Jesus, a Portuguese fort of the 1590s, as a Stone Age site.', '{"question":"Which is a Stone Age site in East Africa?","wrong_answer":"Fort Jesus","correct_answer":"Olduvai Gorge"}'::jsonb, 'The child groups all famous old places together.', 'Offer "Fort Jesus" next to the right answer and ask the question again in a new situation.', 'Sort sites by age: Stone Age sites (Olduvai, Olorgesailie) and later historic buildings (Fort Jesus).', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G9.PEOPLE.SOCIO_ECONOMIC_PRACTICES.STONE_AGE.M_SS9_SA_FIRE_FIRST', 'SOCI.G9.PEOPLE.SOCIO_ECONOMIC_PRACTICES.STONE_AGE', 'Thinks the very first humans already used fire.', '{"question":"Did the earliest Stone Age humans use fire?","wrong_answer":"Yes, from the start","correct_answer":"No, the use of fire came later"}'::jsonb, 'The child pictures cavemen always beside a fire.', 'Offer "Yes, from the start" next to the right answer and ask the question again in a new context.', 'Place "fire" later on the Stone Age timeline.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G9.PEOPLE.INDIGENOUS_KNOWLEDGE_SYS.INDIGENOUS_KNOWLEDGE.M_SS9_IK_WRITTEN', 'SOCI.G9.PEOPLE.INDIGENOUS_KNOWLEDGE_SYS.INDIGENOUS_KNOWLEDGE', 'Says indigenous knowledge was mainly passed on in printed books.', '{"question":"How was indigenous knowledge mainly passed on?","wrong_answer":"By printed books","correct_answer":"By word of mouth"}'::jsonb, 'The child meets this knowledge today in textbooks.', 'Offer "By printed books" next to the right answer and ask the question again in a new situation.', 'Ask an elder to explain a proverb or a weather sign and note that it was never written.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G9.PEOPLE.INDIGENOUS_KNOWLEDGE_SYS.INDIGENOUS_KNOWLEDGE.M_SS9_IK_TYPE', 'SOCI.G9.PEOPLE.INDIGENOUS_KNOWLEDGE_SYS.INDIGENOUS_KNOWLEDGE', 'Names a modern invention such as a computer game as an indigenous knowledge system.', '{"question":"Which is an indigenous knowledge system?","wrong_answer":"A computer game","correct_answer":"Herbal medicine"}'::jsonb, '"Knowledge system" sounds technical, like computers.', 'Offer "A computer game" next to the right answer and ask the question again in a new situation.', 'Sort examples: from elders long ago (herbal medicine, weather signs) or modern.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G9.PEOPLE.INDIGENOUS_KNOWLEDGE_SYS.INDIGENOUS_KNOWLEDGE.M_SS9_IK_USE', 'SOCI.G9.PEOPLE.INDIGENOUS_KNOWLEDGE_SYS.INDIGENOUS_KNOWLEDGE', 'Says indigenous knowledge had no real use.', '{"question":"What was indigenous knowledge used for?","wrong_answer":"Nothing useful","correct_answer":"Sustaining life"}'::jsonb, 'Old ways are often called backward.', 'Offer "Nothing useful" next to the right answer and ask the question again in a new situation.', 'Name a use for each: weather signs for planting, herbs for healing, proverbs for values.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G9.PEOPLE.INDIGENOUS_KNOWLEDGE_SYS.INDIGENOUS_KNOWLEDGE.M_SS9_IK_MODERN_REPLACE', 'SOCI.G9.PEOPLE.INDIGENOUS_KNOWLEDGE_SYS.INDIGENOUS_KNOWLEDGE', 'Thinks modern knowledge has replaced indigenous knowledge completely, so it is never used to decide anything today.', '{"question":"A farmer listens to the radio forecast and also watches for signs elders taught. Is this wise?","wrong_answer":"No, only modern knowledge counts","correct_answer":"Yes, using both can help make better decisions"}'::jsonb, 'Modern science is praised in school.', 'Offer "No, only modern knowledge counts" next to the right answer and ask the question again in a new context.', 'Compare a forecast with a traditional sign for the same season.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G9.PEOPLE.POVERTY_REDUCTION.POVERTY.M_SS9_PO_CAUSE', 'SOCI.G9.PEOPLE.POVERTY_REDUCTION.POVERTY', 'Picks high employment as a cause of poverty.', '{"question":"Which is a cause of poverty?","wrong_answer":"High employment","correct_answer":"Unemployment"}'::jsonb, 'The child reads "employment" and "unemployment" as the same word.', 'Offer "High employment" next to the right answer and ask the question again in a new situation.', 'Underline "un-" and ask what it changes.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G9.PEOPLE.POVERTY_REDUCTION.POVERTY.M_SS9_PO_OVER', 'SOCI.G9.PEOPLE.POVERTY_REDUCTION.POVERTY', 'Thinks using a resource as fast as possible brings wealth for ever.', '{"question":"What can overexploiting resources lead to?","wrong_answer":"Endless wealth","correct_answer":"Empty resources and poverty"}'::jsonb, 'Quick money from charcoal or fish is visible; the empty forest later is not.', 'Offer "Endless wealth" next to the right answer and ask the question again in a new situation.', 'Show a forest cut for charcoal over five years in drawings.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G9.PEOPLE.POVERTY_REDUCTION.POVERTY.M_SS9_PO_GOV', 'SOCI.G9.PEOPLE.POVERTY_REDUCTION.POVERTY', 'Says good governance causes poverty, swapping it with corruption.', '{"question":"Which can lead to poverty?","wrong_answer":"Good governance","correct_answer":"Corruption"}'::jsonb, 'The child picks the governance word without reading "good".', 'Offer "Good governance" next to the right answer and ask the question again in a new situation.', 'Pair: corruption takes money from services; good governance uses it for people.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G9.PEOPLE.POVERTY_REDUCTION.POVERTY.M_SS9_PO_LAZY', 'SOCI.G9.PEOPLE.POVERTY_REDUCTION.POVERTY', 'Thinks poverty is always caused by laziness.', '{"question":"Can a hardworking family be poor?","wrong_answer":"No, only lazy people are poor","correct_answer":"Yes, because of drought, conflict, unemployment or illness"}'::jsonb, 'The child has heard poverty blamed on the poor.', 'Offer "No, only lazy people are poor" next to the right answer and ask the question again in a new context.', 'Read a story of a farming family hit by drought.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G9.PEOPLE.POPULATION_STRUCTURE.POPULATION.M_SS9_PP_SOURCE', 'SOCI.G9.PEOPLE.POPULATION_STRUCTURE.POPULATION', 'Names a rumour or a guess as a source of population data.', '{"question":"Which is a source of population data?","wrong_answer":"A rumour","correct_answer":"The census"}'::jsonb, 'The child hears numbers of people quoted casually.', 'Offer "A rumour" next to the right answer and ask the question again in a new situation.', 'List official sources: census, sample survey, registration of births and deaths.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G9.PEOPLE.POPULATION_STRUCTURE.POPULATION.M_SS9_PP_BASE', 'SOCI.G9.PEOPLE.POPULATION_STRUCTURE.POPULATION', 'Draws a narrow base for a developing country such as Kenya.', '{"question":"What shape has a developing country''s pyramid?","wrong_answer":"A narrow base","correct_answer":"A wide base"}'::jsonb, 'The child pictures a pyramid of stone, wide at the base, and mixes up which country has more children.', 'Offer "A narrow base" next to the right answer and ask the question again in a new situation.', 'Ask which country has more children per family, then make that bar longest at the base.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G9.PEOPLE.POPULATION_STRUCTURE.POPULATION.M_SS9_PP_GERMANY', 'SOCI.G9.PEOPLE.POPULATION_STRUCTURE.POPULATION', 'Draws a very wide base for a developed country such as Germany.', '{"question":"What shape has a developed country''s pyramid?","wrong_answer":"A very wide base","correct_answer":"A narrower base"}'::jsonb, 'The child thinks every pyramid has the same shape.', 'Offer "A very wide base" next to the right answer and ask the question again in a new situation.', 'Compare the two shapes side by side and link each to birth rates.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G9.PEOPLE.POPULATION_STRUCTURE.POPULATION.M_SS9_PP_CENSUS_YEARLY', 'SOCI.G9.PEOPLE.POPULATION_STRUCTURE.POPULATION', 'Thinks the census is taken every year.', '{"question":"How often is Kenya''s census usually taken?","wrong_answer":"Every year","correct_answer":"About every ten years"}'::jsonb, 'The child mixes the census with yearly school registers.', 'Offer "Every year" next to the right answer and ask the question again in a new context.', 'List Kenya''s census years (teacher to give).', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G9.PEOPLE.POPULATION_STRUCTURE.POP_PYRAMIDS.M_SS9_PY_SIDES', 'SOCI.G9.PEOPLE.POPULATION_STRUCTURE.POP_PYRAMIDS', 'Puts the youngest age group at the top of the pyramid.', '{"question":"Where is the youngest age group on a population pyramid?","wrong_answer":"At the top","correct_answer":"At the bottom (the base)"}'::jsonb, 'The child reads charts from the top down.', 'Offer "At the top" next to the right answer and ask the question again in a new context.', 'Label the age groups up the side, 0 to 4 at the bottom.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G9.PEOPLE.POPULATION_STRUCTURE.POP_PYRAMIDS.M_SS9_PY_DEPENDANTS', 'SOCI.G9.PEOPLE.POPULATION_STRUCTURE.POP_PYRAMIDS', 'Thinks only children are dependants, not the elderly.', '{"question":"Which groups are dependants in a population?","wrong_answer":"Only children","correct_answer":"Children and older people"}'::jsonb, 'The child thinks of dependants as children at home.', 'Offer "Only children" next to the right answer and ask the question again in a new context.', 'Shade both the base and the top of a pyramid.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G9.PEOPLE.POPULATION_STRUCTURE.POP_PYRAMIDS.M_SS9_PY_RESOURCE_SAME', 'SOCI.G9.PEOPLE.POPULATION_STRUCTURE.POP_PYRAMIDS', 'Thinks a young and an old population need the same services.', '{"question":"A country has many children. What does it most need?","wrong_answer":"More homes for the elderly","correct_answer":"More schools and health care for mothers and children"}'::jsonb, 'The child does not link the shape to needs.', 'Offer "More homes for the elderly" next to the right answer and ask the question again in a new context.', 'Read the widest bar and ask who those people are.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G9.PEOPLE.POPULATION_STRUCTURE.POP_PYRAMIDS.M_SS9_PY_SCALE', 'SOCI.G9.PEOPLE.POPULATION_STRUCTURE.POP_PYRAMIDS', 'Draws the bars without a scale, so lengths do not match the numbers.', '{"question":"Two age groups have 4 million and 2 million people. How should their bars compare?","wrong_answer":"About the same length","correct_answer":"The first twice as long as the second"}'::jsonb, 'The child draws by eye.', 'Offer "About the same length" next to the right answer and ask the question again in a new context.', 'Use squared paper: 1 square for 1 million.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G9.PEOPLE.PEACEFUL_CONFLICT_RESOLU.PEACE.M_SS9_PE_INNER', 'SOCI.G9.PEOPLE.PEACEFUL_CONFLICT_RESOLU.PEACE', 'Calls peace among nations "inner peace".', '{"question":"What is inner peace?","wrong_answer":"Peace among nations","correct_answer":"Calmness within a person"}'::jsonb, 'The word "inner" is unfamiliar and the child picks the biggest kind of peace.', 'Offer "Peace among nations" next to the right answer and ask the question again in a new situation.', 'Draw circles from the self outwards: inner, between people, community, national.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G9.PEOPLE.PEACEFUL_CONFLICT_RESOLU.PEACE.M_SS9_PE_BARRIER', 'SOCI.G9.PEOPLE.PEACEFUL_CONFLICT_RESOLU.PEACE', 'Names listening as a barrier to resolving conflict.', '{"question":"Which is a barrier to conflict resolution?","wrong_answer":"Listening","correct_answer":"Prejudice"}'::jsonb, 'The child reads the question as "what is involved" rather than "what blocks".', 'Offer "Listening" next to the right answer and ask the question again in a new situation.', 'Sort cards into "helps" and "blocks" before answering.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G9.PEOPLE.PEACEFUL_CONFLICT_RESOLU.PEACE.M_SS9_PE_EQ', 'SOCI.G9.PEOPLE.PEACEFUL_CONFLICT_RESOLU.PEACE', 'Thinks emotional intelligence means feeling anger strongly.', '{"question":"What does emotional intelligence help with?","wrong_answer":"Fuelling anger","correct_answer":"Managing emotions"}'::jsonb, '"Emotional" suggests strong feelings.', 'Offer "Fuelling anger" next to the right answer and ask the question again in a new situation.', 'Define it as understanding and managing feelings, your own and others''.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G9.PEOPLE.PEACEFUL_CONFLICT_RESOLU.PEACE.M_SS9_PE_ABSENCE', 'SOCI.G9.PEOPLE.PEACEFUL_CONFLICT_RESOLU.PEACE', 'Thinks peace only means there is no war.', '{"question":"A village has no fighting but people do not trust each other. Is there full peace?","wrong_answer":"Yes, there is no war","correct_answer":"No, peace also needs trust, justice and cooperation"}'::jsonb, 'Peace is taught as the opposite of war.', 'Offer "Yes, there is no war" next to the right answer and ask the question again in a new context.', 'Compare a quiet but divided village with a united one.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G9.PEOPLE.PEACEFUL_CONFLICT_RESOLU.EMOTIONS_PEACE.M_SS9_EP_SUPPRESS', 'SOCI.G9.PEOPLE.PEACEFUL_CONFLICT_RESOLU.EMOTIONS_PEACE', 'Thinks managing emotions means pretending not to have them.', '{"question":"What does managing anger mean?","wrong_answer":"Pretending you are not angry","correct_answer":"Noticing the anger and calming down before acting"}'::jsonb, 'The child has been told to hide feelings.', 'Offer "Pretending you are not angry" next to the right answer and ask the question again in a new context.', 'Practise naming a feeling aloud, then the pause-breathe-speak routine.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G9.PEOPLE.PEACEFUL_CONFLICT_RESOLU.EMOTIONS_PEACE.M_SS9_EP_EMPATHY_AGREE', 'SOCI.G9.PEOPLE.PEACEFUL_CONFLICT_RESOLU.EMOTIONS_PEACE', 'Thinks empathy means agreeing with the other side.', '{"question":"Can you show empathy to someone you disagree with?","wrong_answer":"No, empathy means agreeing","correct_answer":"Yes, by understanding how they feel"}'::jsonb, 'Empathy and agreement are mixed up.', 'Offer "No, empathy means agreeing" next to the right answer and ask the question again in a new context.', 'Role-play understanding a view without accepting it.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G9.PEOPLE.PEACEFUL_CONFLICT_RESOLU.EMOTIONS_PEACE.M_SS9_EP_REACT_FAST', 'SOCI.G9.PEOPLE.PEACEFUL_CONFLICT_RESOLU.EMOTIONS_PEACE', 'Thinks a quick angry reply shows strength in a community quarrel.', '{"question":"At a community meeting, someone insults your family. What shows emotional intelligence?","wrong_answer":"Shout back at once","correct_answer":"Pause, stay calm and answer respectfully or speak later"}'::jsonb, 'Quick replies look strong.', 'Offer "Shout back at once" next to the right answer and ask the question again in a new context.', 'Count to ten together, then reply.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G9.PEOPLE.PEACEFUL_CONFLICT_RESOLU.EMOTIONS_PEACE.M_SS9_EP_SELF_ONLY', 'SOCI.G9.PEOPLE.PEACEFUL_CONFLICT_RESOLU.EMOTIONS_PEACE', 'Thinks emotional intelligence is only about your own feelings, not others''.', '{"question":"Which part of emotional intelligence is about other people''s feelings?","wrong_answer":"None of it","correct_answer":"Empathy and social skills"}'::jsonb, 'Self-awareness is taught first.', 'Offer "None of it" next to the right answer and ask the question again in a new context.', 'List the five parts and mark which face outward.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G9.PEOPLE.HEALTHY_RELATIONSHIPS.RELATIONSHIPS.M_SS9_RL_WAY', 'SOCI.G9.PEOPLE.HEALTHY_RELATIONSHIPS.RELATIONSHIPS', 'Picks gossip as a way of sustaining a healthy relationship.', '{"question":"Which sustains a healthy relationship?","wrong_answer":"Gossip","correct_answer":"Respect"}'::jsonb, 'Sharing gossip can feel like closeness with a friend.', 'Offer "Gossip" next to the right answer and ask the question again in a new situation.', 'Ask how the person being gossiped about feels and what happens to trust.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G9.PEOPLE.HEALTHY_RELATIONSHIPS.RELATIONSHIPS.M_SS9_RL_BARRIER', 'SOCI.G9.PEOPLE.HEALTHY_RELATIONSHIPS.RELATIONSHIPS', 'Names trust as a barrier to a healthy relationship.', '{"question":"Which is a barrier to a healthy relationship?","wrong_answer":"Trust","correct_answer":"Jealousy"}'::jsonb, 'The child reads the question as "what is part of a relationship".', 'Offer "Trust" next to the right answer and ask the question again in a new situation.', 'Sort cards into "builds" and "breaks".', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G9.PEOPLE.HEALTHY_RELATIONSHIPS.RELATIONSHIPS.M_SS9_RL_FORGIVE', 'SOCI.G9.PEOPLE.HEALTHY_RELATIONSHIPS.RELATIONSHIPS', 'Thinks forgiving ends a friendship or shows weakness.', '{"question":"What does forgiveness do?","wrong_answer":"Ends the friendship","correct_answer":"Heals the relationship"}'::jsonb, 'Standing firm is admired and forgiving looks like giving in.', 'Offer "Ends the friendship" next to the right answer and ask the question again in a new situation.', 'Tell a story where forgiveness saved a friendship.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G9.PEOPLE.HEALTHY_RELATIONSHIPS.RELATIONSHIPS.M_SS9_RL_BOUNDARY', 'SOCI.G9.PEOPLE.HEALTHY_RELATIONSHIPS.RELATIONSHIPS', 'Thinks saying no to a friend always harms the relationship.', '{"question":"Can saying no to a friend''s harmful request keep the friendship healthy?","wrong_answer":"No, it ruins it","correct_answer":"Yes, healthy friends respect each other''s limits"}'::jsonb, 'The child fears losing friends.', 'Offer "No, it ruins it" next to the right answer and ask the question again in a new context.', 'Role-play a kind but firm no.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G9.NATURA.TOPOGRAPHICAL_MAPS.TOPO_MAPS.M_SS9_TM_CONTOUR', 'SOCI.G9.NATURA.TOPOGRAPHICAL_MAPS.TOPO_MAPS', 'Reads contour lines as roads.', '{"question":"What do contour lines show?","wrong_answer":"Roads","correct_answer":"Height of the land"}'::jsonb, 'Most lines the child has seen on maps are roads.', 'Offer "Roads" next to the right answer and ask the question again in a new situation.', 'Check the key; follow a contour round a hill and see it never leads anywhere.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G9.NATURA.TOPOGRAPHICAL_MAPS.TOPO_MAPS.M_SS9_TM_SECTION', 'SOCI.G9.NATURA.TOPOGRAPHICAL_MAPS.TOPO_MAPS', 'Thinks a cross-section shows the map title or the view from above.', '{"question":"What does a cross-section show?","wrong_answer":"The map''s title","correct_answer":"The shape of the land along a line"}'::jsonb, 'The child has only seen maps drawn from above.', 'Offer "The map''s title" next to the right answer and ask the question again in a new situation.', 'Cut a loaf or a clay hill and show the side view.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G9.NATURA.TOPOGRAPHICAL_MAPS.TOPO_MAPS.M_SS9_TM_HUMAN', 'SOCI.G9.NATURA.TOPOGRAPHICAL_MAPS.TOPO_MAPS', 'Names a river as a human activity shown on the map.', '{"question":"Which is a human activity shown on a map?","wrong_answer":"A river","correct_answer":"A railway"}'::jsonb, 'Everything on a map seems to be about people''s use.', 'Offer "A river" next to the right answer and ask the question again in a new situation.', 'Sort map features into natural and made by people.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G9.NATURA.TOPOGRAPHICAL_MAPS.TOPO_MAPS.M_SS9_TM_ENLARGE_SCALE', 'SOCI.G9.NATURA.TOPOGRAPHICAL_MAPS.TOPO_MAPS', 'Thinks enlarging a map makes the scale number bigger (1:50,000 becomes 1:100,000).', '{"question":"A map at 1:50,000 is enlarged two times. What is the new scale?","wrong_answer":"1:100,000","correct_answer":"1:25,000"}'::jsonb, 'Bigger map seems to mean bigger number.', 'Offer "1:100,000" next to the right answer and ask the question again in a new context.', 'Show that on the enlarged map each centimetre covers less ground.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G9.NATURA.INTERNAL_LAND_FORMING_PR.LAND_FORMING.M_SS9_LF_TENSION', 'SOCI.G9.NATURA.INTERNAL_LAND_FORMING_PR.LAND_FORMING', 'Says compressional forces pull the crust apart, swapping them with tensional forces.', '{"question":"Which force pulls the crust apart?","wrong_answer":"Compressional","correct_answer":"Tensional"}'::jsonb, 'The two technical words are learnt together.', 'Offer "Compressional" next to the right answer and ask the question again in a new situation.', 'Act it with hands: pull apart (tension), push together (compression).', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G9.NATURA.INTERNAL_LAND_FORMING_PR.LAND_FORMING.M_SS9_LF_RIFT', 'SOCI.G9.NATURA.INTERNAL_LAND_FORMING_PR.LAND_FORMING', 'Names a delta as a feature of faulting.', '{"question":"Which feature is made by faulting?","wrong_answer":"A delta","correct_answer":"A rift valley"}'::jsonb, 'Deltas and rift valleys are both landforms in the same chapter.', 'Offer "A delta" next to the right answer and ask the question again in a new situation.', 'Sort landforms into those made by rivers and those made by faulting.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G9.NATURA.INTERNAL_LAND_FORMING_PR.LAND_FORMING.M_SS9_LF_EFFECT', 'SOCI.G9.NATURA.INTERNAL_LAND_FORMING_PR.LAND_FORMING', 'Thinks faulting has no effect on people.', '{"question":"Which can faulting bring?","wrong_answer":"Nothing at all","correct_answer":"Earthquakes and hot springs"}'::jsonb, 'Faulting happened long ago, so it seems irrelevant now.', 'Offer "Nothing at all" next to the right answer and ask the question again in a new situation.', 'List faulting effects in Kenya: Rift Valley lakes, hot springs, geothermal power, earthquakes.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G9.NATURA.INTERNAL_LAND_FORMING_PR.LAND_FORMING.M_SS9_LF_GEOTHERMAL', 'SOCI.G9.NATURA.INTERNAL_LAND_FORMING_PR.LAND_FORMING', 'Does not link faulting in the Rift Valley to geothermal power at Olkaria.', '{"question":"How does the Rift Valley help Kenya make electricity?","wrong_answer":"It does not","correct_answer":"Heat from underground near the faults is used at Olkaria for geothermal power"}'::jsonb, 'The child links electricity only to dams.', 'Offer "It does not" next to the right answer and ask the question again in a new context.', 'Show Olkaria on the map with steam pipes.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G9.NATURA.INTERNAL_LAND_FORMING_PR.PLATE_TECTONICS.M_SS9_PT_FIXED', 'SOCI.G9.NATURA.INTERNAL_LAND_FORMING_PR.PLATE_TECTONICS', 'Thinks the continents have always been where they are now.', '{"question":"Have the continents always been in the same place?","wrong_answer":"Yes","correct_answer":"No, they were once joined and slowly moved apart"}'::jsonb, 'The ground feels fixed.', 'Offer "Yes" next to the right answer and ask the question again in a new context.', 'Fit the coasts of Africa and South America together.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G9.NATURA.INTERNAL_LAND_FORMING_PR.PLATE_TECTONICS.M_SS9_PT_FAST', 'SOCI.G9.NATURA.INTERNAL_LAND_FORMING_PR.PLATE_TECTONICS', 'Thinks continents move fast enough to notice in a lifetime.', '{"question":"How fast do the plates move?","wrong_answer":"Many kilometres a year","correct_answer":"A few centimetres a year, about as fast as fingernails grow"}'::jsonb, 'The child imagines dramatic movement.', 'Offer "Many kilometres a year" next to the right answer and ask the question again in a new context.', 'Compare with fingernail growth.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G9.NATURA.INTERNAL_LAND_FORMING_PR.PLATE_TECTONICS.M_SS9_PT_EVIDENCE', 'SOCI.G9.NATURA.INTERNAL_LAND_FORMING_PR.PLATE_TECTONICS', 'Cannot give evidence for continental drift.', '{"question":"Give one piece of evidence for continental drift.","wrong_answer":"There is none","correct_answer":"The coasts of Africa and South America fit together, and matching fossils are found on both"}'::jsonb, 'The idea is taught as a story.', 'Offer "There is none" next to the right answer and ask the question again in a new context.', 'Show matching fossil maps across the Atlantic.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G9.NATURA.INTERNAL_LAND_FORMING_PR.PLATE_TECTONICS.M_SS9_PT_PLATE_COUNTRY', 'SOCI.G9.NATURA.INTERNAL_LAND_FORMING_PR.PLATE_TECTONICS', 'Thinks each country sits on its own plate.', '{"question":"Does each country have its own plate?","wrong_answer":"Yes","correct_answer":"No, a plate is huge and carries many countries and oceans"}'::jsonb, 'Plates and countries are both drawn as shapes on maps.', 'Offer "Yes" next to the right answer and ask the question again in a new context.', 'Show the African plate covering many countries.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G9.NATURA.MULTI_PURPOSE_RIVER_PROJ.RIVER_PROJECTS.M_SS9_RV_RIVER', 'SOCI.G9.NATURA.MULTI_PURPOSE_RIVER_PROJ.RIVER_PROJECTS', 'Puts the Aswan High Dam on the Zambezi, swapping it with Kariba.', '{"question":"On which river is the Aswan High Dam?","wrong_answer":"The Zambezi","correct_answer":"The Nile"}'::jsonb, 'Two big dams on two big rivers are learnt together.', 'Offer "The Zambezi" next to the right answer and ask the question again in a new situation.', 'Pair each dam with its river and country on the map.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G9.NATURA.MULTI_PURPOSE_RIVER_PROJ.RIVER_PROJECTS.M_SS9_RV_USE', 'SOCI.G9.NATURA.MULTI_PURPOSE_RIVER_PROJ.RIVER_PROJECTS', 'Names causing drought as a use of a multi-purpose dam.', '{"question":"Which is a use of a multi-purpose dam?","wrong_answer":"Causing drought","correct_answer":"Producing electricity"}'::jsonb, 'The child reads "use" as "effect".', 'Offer "Causing drought" next to the right answer and ask the question again in a new situation.', 'List what a dam is built to give: power, irrigation, water, flood control, fish.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G9.NATURA.MULTI_PURPOSE_RIVER_PROJ.RIVER_PROJECTS.M_SS9_RV_CHALLENGE', 'SOCI.G9.NATURA.MULTI_PURPOSE_RIVER_PROJ.RIVER_PROJECTS', 'Names cheap power, a benefit, as a challenge of a big dam.', '{"question":"Which is a challenge of a big dam?","wrong_answer":"Cheap power","correct_answer":"Displacing people"}'::jsonb, 'The child picks a familiar dam word without sorting good from bad.', 'Offer "Cheap power" next to the right answer and ask the question again in a new situation.', 'Sort dam facts into benefits and challenges.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G9.NATURA.MULTI_PURPOSE_RIVER_PROJ.RIVER_PROJECTS.M_SS9_RV_ONE_USE', 'SOCI.G9.NATURA.MULTI_PURPOSE_RIVER_PROJ.RIVER_PROJECTS', 'Thinks a multi-purpose project only makes electricity.', '{"question":"Why is Aswan called a multi-purpose project?","wrong_answer":"It only makes electricity","correct_answer":"It gives power, irrigation water, flood control and fish"}'::jsonb, 'Dams are known for power.', 'Offer "It only makes electricity" next to the right answer and ask the question again in a new context.', 'Break the word: multi = many purposes.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G9.NATURA.MULTI_PURPOSE_RIVER_PROJ.RIVER_CONDITIONS.M_SS9_RC_FLAT_SITE', 'SOCI.G9.NATURA.MULTI_PURPOSE_RIVER_PROJ.RIVER_CONDITIONS', 'Thinks a flat, wide plain is the best place for a dam.', '{"question":"Which site suits a dam on the Tana: a deep gorge or a flat plain?","wrong_answer":"A flat plain","correct_answer":"A deep gorge with hard rock"}'::jsonb, 'Flat land seems easy to build on.', 'Offer "A flat plain" next to the right answer and ask the question again in a new context.', 'Model water held by a narrow gorge and spreading on a plain.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G9.NATURA.MULTI_PURPOSE_RIVER_PROJ.RIVER_CONDITIONS.M_SS9_RC_SEASONAL', 'SOCI.G9.NATURA.MULTI_PURPOSE_RIVER_PROJ.RIVER_CONDITIONS', 'Thinks any seasonal river can feed a big dam.', '{"question":"Why was the Tana chosen for the Seven Forks dams?","wrong_answer":"Any river would do","correct_answer":"It is a permanent river with plenty of water all year"}'::jsonb, 'The child does not think about dry seasons.', 'Offer "Any river would do" next to the right answer and ask the question again in a new context.', 'Compare the Tana with a river that dries up.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G9.NATURA.MULTI_PURPOSE_RIVER_PROJ.RIVER_CONDITIONS.M_SS9_RC_SILT_FIX', 'SOCI.G9.NATURA.MULTI_PURPOSE_RIVER_PROJ.RIVER_CONDITIONS', 'Thinks silting is solved by building a bigger wall.', '{"question":"Which solution fits silting of a dam?","wrong_answer":"Build a higher wall","correct_answer":"Plant trees and stop soil erosion in the catchment"}'::jsonb, 'A bigger wall seems to hold more.', 'Offer "Build a higher wall" next to the right answer and ask the question again in a new context.', 'Trace the silt back to bare hills upstream.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G9.NATURA.MULTI_PURPOSE_RIVER_PROJ.RIVER_CONDITIONS.M_SS9_RC_DISPLACED', 'SOCI.G9.NATURA.MULTI_PURPOSE_RIVER_PROJ.RIVER_CONDITIONS', 'Thinks moving people for a dam needs no plan or compensation.', '{"question":"People must move for a new dam. What is fair?","wrong_answer":"Just move them","correct_answer":"Consult them, compensate fairly and resettle them well"}'::jsonb, 'The project seems more important than the people.', 'Offer "Just move them" next to the right answer and ask the question again in a new context.', 'Read a story of families moved without help.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G9.NATURA.MANAGEMENT_AND_CONSERVAT.ENV_DEGRADATION.M_SS9_ED_CAUSE', 'SOCI.G9.NATURA.MANAGEMENT_AND_CONSERVAT.ENV_DEGRADATION', 'Names planting trees as a cause of environmental degradation.', '{"question":"Which causes environmental degradation?","wrong_answer":"Planting trees","correct_answer":"Deforestation"}'::jsonb, 'The child reads the question as "what is done to the environment".', 'Offer "Planting trees" next to the right answer and ask the question again in a new situation.', 'Sort actions into "harms" and "heals".', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G9.NATURA.MANAGEMENT_AND_CONSERVAT.ENV_DEGRADATION.M_SS9_ED_EFFECT', 'SOCI.G9.NATURA.MANAGEMENT_AND_CONSERVAT.ENV_DEGRADATION', 'Gives "better soil" as an effect of degradation.', '{"question":"Which is an effect of degradation?","wrong_answer":"Better soil","correct_answer":"Soil erosion"}'::jsonb, 'The child guesses a familiar soil phrase.', 'Offer "Better soil" next to the right answer and ask the question again in a new situation.', 'Show a gully photo and ask what happened to the soil.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G9.NATURA.MANAGEMENT_AND_CONSERVAT.ENV_DEGRADATION.M_SS9_ED_ANSWER', 'SOCI.G9.NATURA.MANAGEMENT_AND_CONSERVAT.ENV_DEGRADATION', 'Names burning forests as a way to conserve the environment.', '{"question":"Which helps to conserve the environment?","wrong_answer":"Burning forests","correct_answer":"Terracing and afforestation"}'::jsonb, 'Burning clears land and seems to "clean" it.', 'Offer "Burning forests" next to the right answer and ask the question again in a new situation.', 'Compare land after burning with land after tree planting.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G9.NATURA.MANAGEMENT_AND_CONSERVAT.ENV_DEGRADATION.M_SS9_ED_PLASTIC_HARMLESS', 'SOCI.G9.NATURA.MANAGEMENT_AND_CONSERVAT.ENV_DEGRADATION', 'Thinks plastic waste is harmless because it does not rot.', '{"question":"Why is plastic waste harmful to the environment?","wrong_answer":"It is harmless, it does not rot","correct_answer":"It lasts for years, blocks drains, harms animals and soil"}'::jsonb, 'Not rotting sounds clean.', 'Offer "It is harmless, it does not rot" next to the right answer and ask the question again in a new context.', 'Show a blocked drain and a cow that ate plastic.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G9.NATURA.WORLD_HERITAGE_SITES_IN_.HERITAGE_SITES.M_SS9_HS_LAMU', 'SOCI.G9.NATURA.WORLD_HERITAGE_SITES_IN_.HERITAGE_SITES', 'Places Lamu Old Town in Tanzania because Swahili towns line both coasts.', '{"question":"In which country is Lamu Old Town?","wrong_answer":"Tanzania","correct_answer":"Kenya"}'::jsonb, 'Lamu and Zanzibar''s Stone Town are both Swahili towns and the child swaps them.', 'Offer "Tanzania" next to the right answer and ask the question again in a new situation.', 'Pin Lamu and Stone Town on the coast map.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G9.NATURA.WORLD_HERITAGE_SITES_IN_.HERITAGE_SITES.M_SS9_HS_PYRAMIDS', 'SOCI.G9.NATURA.WORLD_HERITAGE_SITES_IN_.HERITAGE_SITES', 'Places the Pyramids of Giza in Kenya.', '{"question":"In which country are the Pyramids of Giza?","wrong_answer":"Kenya","correct_answer":"Egypt"}'::jsonb, 'The child guesses their own country for any famous site.', 'Offer "Kenya" next to the right answer and ask the question again in a new situation.', 'Pin the Pyramids in Egypt on the Africa map.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G9.NATURA.WORLD_HERITAGE_SITES_IN_.HERITAGE_SITES.M_SS9_HS_WHY', 'SOCI.G9.NATURA.WORLD_HERITAGE_SITES_IN_.HERITAGE_SITES', 'Says heritage sites are kept for no reason.', '{"question":"Why are heritage sites kept?","wrong_answer":"For no reason","correct_answer":"For culture, history and tourism"}'::jsonb, 'Old places look unused to the child.', 'Offer "For no reason" next to the right answer and ask the question again in a new situation.', 'List what a site gives: history, identity, tourism, jobs.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G9.NATURA.WORLD_HERITAGE_SITES_IN_.HERITAGE_SITES.M_SS9_HS_NATURAL_NOT', 'SOCI.G9.NATURA.WORLD_HERITAGE_SITES_IN_.HERITAGE_SITES', 'Thinks World Heritage sites can only be buildings, not natural places.', '{"question":"Can a natural place like Mount Kenya be a World Heritage site?","wrong_answer":"No, only buildings","correct_answer":"Yes, natural sites are listed too"}'::jsonb, 'Heritage sounds like old buildings.', 'Offer "No, only buildings" next to the right answer and ask the question again in a new context.', 'Show Mount Kenya and Lake Turkana on the list.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G9.POLITI.THE_CONSTITUTION_OF_KENY.CONSTITUTION_MAKING.M_SS9_CM_ORDER', 'SOCI.G9.POLITI.THE_CONSTITUTION_OF_KENY.CONSTITUTION_MAKING', 'Puts the referendum first, before views were collected and a draft written.', '{"question":"Which stage comes first?","wrong_answer":"The referendum","correct_answer":"Collecting views"}'::jsonb, 'The referendum is the best-remembered event.', 'Offer "The referendum" next to the right answer and ask the question again in a new situation.', 'Ask: what did people vote on? A draft must exist first.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G9.POLITI.THE_CONSTITUTION_OF_KENY.CONSTITUTION_MAKING.M_SS9_CM_PARLIAMENT', 'SOCI.G9.POLITI.THE_CONSTITUTION_OF_KENY.CONSTITUTION_MAKING', 'Says Parliament ignores the draft constitution.', '{"question":"What does Parliament do with the draft?","wrong_answer":"Ignores it","correct_answer":"Debates and approves it"}'::jsonb, 'The child knows citizens voted and does not see Parliament''s part.', 'Offer "Ignores it" next to the right answer and ask the question again in a new situation.', 'Show Parliament debating and approving the draft before the referendum.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G9.POLITI.THE_CONSTITUTION_OF_KENY.CONSTITUTION_MAKING.M_SS9_CM_YEAR', 'SOCI.G9.POLITI.THE_CONSTITUTION_OF_KENY.CONSTITUTION_MAKING', 'Gives 2002 (when the review began) as the year the Constitution was promulgated.', '{"question":"In which year was Kenya''s current Constitution promulgated?","wrong_answer":"2002","correct_answer":"2010"}'::jsonb, 'The review process started years before 2010, and the child remembers an early date.', 'Offer "2002" next to the right answer and ask the question again in a new situation.', 'Put 2002 (review begins) and 2010 (referendum and promulgation) on a timeline.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G9.POLITI.THE_CONSTITUTION_OF_KENY.CONSTITUTION_MAKING.M_SS9_CM_CITIZENS_NONE', 'SOCI.G9.POLITI.THE_CONSTITUTION_OF_KENY.CONSTITUTION_MAKING', 'Thinks ordinary citizens had no part in making the Constitution.', '{"question":"How did citizens take part in making the 2010 Constitution?","wrong_answer":"They did not","correct_answer":"They gave their views and voted in the referendum"}'::jsonb, 'Law-making seems to belong to leaders.', 'Offer "They did not" next to the right answer and ask the question again in a new context.', 'List the two citizen stages on the timeline.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G9.POLITI.CIVIC_ENGAGEMENT_IN_GOVE.CIVIC_ENGAGEMENT.M_SS9_CE_ACT', 'SOCI.G9.POLITI.CIVIC_ENGAGEMENT_IN_GOVE.CIVIC_ENGAGEMENT', 'Names skipping school as a civic activity.', '{"question":"Which is a civic activity?","wrong_answer":"Skipping school","correct_answer":"Voting"}'::jsonb, 'The child reads "activity" without "civic".', 'Offer "Skipping school" next to the right answer and ask the question again in a new situation.', 'Define civic: taking part in public life for the common good.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G9.POLITI.CIVIC_ENGAGEMENT_IN_GOVE.CIVIC_ENGAGEMENT.M_SS9_CE_PARTY', 'SOCI.G9.POLITI.CIVIC_ENGAGEMENT_IN_GOVE.CIVIC_ENGAGEMENT', 'Says political parties close schools.', '{"question":"What do political parties do?","wrong_answer":"Close schools","correct_answer":"Field candidates in elections"}'::jsonb, 'The child guesses from news of protests.', 'Offer "Close schools" next to the right answer and ask the question again in a new situation.', 'List what parties do: field candidates, share policies, give citizens a voice.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G9.POLITI.CIVIC_ENGAGEMENT_IN_GOVE.CIVIC_ENGAGEMENT.M_SS9_CE_POST', 'SOCI.G9.POLITI.CIVIC_ENGAGEMENT_IN_GOVE.CIVIC_ENGAGEMENT', 'Names the head teacher as a post vied for at a general election.', '{"question":"Which post is vied for in a general election?","wrong_answer":"Head teacher","correct_answer":"Governor"}'::jsonb, 'The child mixes school elections with national ones.', 'Offer "Head teacher" next to the right answer and ask the question again in a new situation.', 'List the six posts on the general election ballot.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G9.POLITI.CIVIC_ENGAGEMENT_IN_GOVE.CIVIC_ENGAGEMENT.M_SS9_CE_COLLECTIVE', 'SOCI.G9.POLITI.CIVIC_ENGAGEMENT_IN_GOVE.CIVIC_ENGAGEMENT', 'Cannot tell individual from collective civic engagement.', '{"question":"A youth group cleans a market together. Is this individual or collective civic engagement?","wrong_answer":"Individual","correct_answer":"Collective"}'::jsonb, 'The child does not notice who acts.', 'Offer "Individual" next to the right answer and ask the question again in a new context.', 'Sort examples by "one person" or "a group".', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G9.POLITI.KENYA_S_BILL_OF_RIGHTS.BILL_OF_RIGHTS.M_SS9_BR_CHAPTER', 'SOCI.G9.POLITI.KENYA_S_BILL_OF_RIGHTS.BILL_OF_RIGHTS', 'Says the Bill of Rights is Chapter 1 of the Constitution.', '{"question":"In which chapter is the Bill of Rights?","wrong_answer":"Chapter 1","correct_answer":"Chapter 4"}'::jsonb, 'The child thinks the most important part must come first.', 'Offer "Chapter 1" next to the right answer and ask the question again in a new situation.', 'Show the chapter list: Chapter 1 is Sovereignty, Chapter 4 the Bill of Rights.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G9.POLITI.KENYA_S_BILL_OF_RIGHTS.BILL_OF_RIGHTS.M_SS9_BR_RIGHT', 'SOCI.G9.POLITI.KENYA_S_BILL_OF_RIGHTS.BILL_OF_RIGHTS', 'Names "the right to cheat" as a right in the Bill of Rights.', '{"question":"Which is a right in the Bill of Rights?","wrong_answer":"The right to cheat","correct_answer":"The right to life"}'::jsonb, 'The child guesses "right to" plus any action.', 'Offer "The right to cheat" next to the right answer and ask the question again in a new situation.', 'Read three real rights and ask whether each protects dignity.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G9.POLITI.KENYA_S_BILL_OF_RIGHTS.BILL_OF_RIGHTS.M_SS9_BR_SPECIAL', 'SOCI.G9.POLITI.KENYA_S_BILL_OF_RIGHTS.BILL_OF_RIGHTS', 'Names adults with jobs as a special group needing protection.', '{"question":"Which is a special group protected by the Constitution?","wrong_answer":"Only adults with jobs","correct_answer":"Persons with disabilities"}'::jsonb, 'The child does not link special protection to vulnerability.', 'Offer "Only adults with jobs" next to the right answer and ask the question again in a new situation.', 'Ask who is more likely to be left out or harmed.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G9.POLITI.KENYA_S_BILL_OF_RIGHTS.BILL_OF_RIGHTS.M_SS9_BR_LIMITLESS', 'SOCI.G9.POLITI.KENYA_S_BILL_OF_RIGHTS.BILL_OF_RIGHTS', 'Thinks rights in the Bill of Rights have no limits at all.', '{"question":"Can the right to free expression be used to spread hate speech?","wrong_answer":"Yes, it has no limits","correct_answer":"No, it does not cover hate speech or incitement"}'::jsonb, 'Rights are taught as freedoms.', 'Offer "Yes, it has no limits" next to the right answer and ask the question again in a new context.', 'Read the limit on expression in the Constitution.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G9.POLITI.CULTURAL_GLOBALISATION.GLOBAL_CULTURE.M_SS9_GC_ELEMENT', 'SOCI.G9.POLITI.CULTURAL_GLOBALISATION.GLOBAL_CULTURE', 'Names the price of petrol as an element of culture.', '{"question":"Which is an element of culture?","wrong_answer":"The price of petrol","correct_answer":"Language and music"}'::jsonb, 'The child thinks anything people talk about is culture.', 'Offer "The price of petrol" next to the right answer and ask the question again in a new situation.', 'List the elements: language, music, dance, dress, food, sport, beliefs.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G9.POLITI.CULTURAL_GLOBALISATION.GLOBAL_CULTURE.M_SS9_GC_KISWAHILI', 'SOCI.G9.POLITI.CULTURAL_GLOBALISATION.GLOBAL_CULTURE', 'Says no Kenyan language has world recognition.', '{"question":"Which Kenyan language has global recognition?","wrong_answer":"None has any","correct_answer":"Kiswahili"}'::jsonb, 'The child thinks only English and other foreign languages are global.', 'Offer "None has any" next to the right answer and ask the question again in a new situation.', 'Show Kiswahili used in the African Union and taught abroad.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G9.POLITI.CULTURAL_GLOBALISATION.GLOBAL_CULTURE.M_SS9_GC_HUMANITY', 'SOCI.G9.POLITI.CULTURAL_GLOBALISATION.GLOBAL_CULTURE', 'Picks mocking other cultures as a way to promote a common humanity.', '{"question":"What promotes a common humanity?","wrong_answer":"Mocking other cultures","correct_answer":"Respect and dialogue"}'::jsonb, 'Jokes about other groups are common and seem harmless.', 'Offer "Mocking other cultures" next to the right answer and ask the question again in a new situation.', 'Ask how the mocked group feels and whether it brings people together.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G9.POLITI.CULTURAL_GLOBALISATION.GLOBAL_CULTURE.M_SS9_GC_LOSE_ALL', 'SOCI.G9.POLITI.CULTURAL_GLOBALISATION.GLOBAL_CULTURE', 'Thinks sharing culture with the world means losing it.', '{"question":"Does sharing Kenyan music with the world mean Kenya loses it?","wrong_answer":"Yes","correct_answer":"No, it can spread and be preserved"}'::jsonb, 'The child sees globalisation as only taking away.', 'Offer "Yes" next to the right answer and ask the question again in a new context.', 'Show Kenyan music played abroad and still at home.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G9.POLITI.CULTURAL_GLOBALISATION.CULTURE_FACTORS.M_SS9_CF_STEREOTYPE', 'SOCI.G9.POLITI.CULTURAL_GLOBALISATION.CULTURE_FACTORS', 'Thinks stereotypes help people understand other cultures.', '{"question":"Do stereotypes help healthy cultural relationships?","wrong_answer":"Yes, they explain people quickly","correct_answer":"No, they spread wrong ideas and disrespect"}'::jsonb, 'Stereotypes feel like knowledge.', 'Offer "Yes, they explain people quickly" next to the right answer and ask the question again in a new context.', 'Test a stereotype against real people from that culture.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G9.POLITI.CULTURAL_GLOBALISATION.CULTURE_FACTORS.M_SS9_CF_LANGUAGE_NONE', 'SOCI.G9.POLITI.CULTURAL_GLOBALISATION.CULTURE_FACTORS', 'Does not see learning another language as helping cultural relationships.', '{"question":"How does learning another language help cultural relationships?","wrong_answer":"It does not","correct_answer":"It helps people understand and respect each other"}'::jsonb, 'Language is seen only as a school subject.', 'Offer "It does not" next to the right answer and ask the question again in a new context.', 'Greet a visitor in their language and see the reaction.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G9.POLITI.CULTURAL_GLOBALISATION.CULTURE_FACTORS.M_SS9_CF_MEDIA_ALL_GOOD', 'SOCI.G9.POLITI.CULTURAL_GLOBALISATION.CULTURE_FACTORS', 'Thinks all media spread healthy cultural relationships.', '{"question":"Can the media harm cultural relationships?","wrong_answer":"No, media only help","correct_answer":"Yes, if they spread stereotypes or hate"}'::jsonb, 'Media are seen as neutral.', 'Offer "No, media only help" next to the right answer and ask the question again in a new context.', 'Compare a respectful programme with a mocking post.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('SOCI.G9.POLITI.CULTURAL_GLOBALISATION.CULTURE_FACTORS.M_SS9_CF_EXCHANGE_NONE', 'SOCI.G9.POLITI.CULTURAL_GLOBALISATION.CULTURE_FACTORS', 'Does not see cultural exchange as a factor of healthy relationships.', '{"question":"How do cultural festivals and exchange programmes help?","wrong_answer":"They do not","correct_answer":"People meet, share and learn to respect each other"}'::jsonb, 'Festivals seem only for fun.', 'Offer "They do not" next to the right answer and ask the question again in a new context.', 'Recall a school culture day and what learners learnt.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
